"use strict";
const fixtures={
stock:{title:"Kartu Persediaan Barang Jadi",subtitle:"Mutasi dan saldo per SKU (DATA DEMO)",headers:["SKU","Merek","Saldo awal","Masuk","Keluar","Saldo akhir","Status"],rows:[["C-033","Contoh GCC isi 12",12000,4000,3000,13000,"WORKING"],["C-036","Contoh isi 16",8000,5000,4000,9000,"OPEN RECON"],["C-012","Contoh Cengkeh isi 12",1000,2000,1000,2000,"WORKING"]]},
wip:{title:"Laporan WIP Giling–Verpack",subtitle:"Tray, batang dan potensi kemasan (DATA DEMO)",headers:["SKU","Lot","Tray","Batang/tray","Batang","Potensi pack","Status"],rows:[["C-033","DEMO-LOT-01",10,1500,15000,1250,"WORKING"],["C-033","DEMO-LOT-02",5,1500,7500,625,"OPEN RECON"]]},
gap:{title:"Rekonsiliasi Gap Antardivisi",subtitle:"Register penyimpangan dan tindakan (DATA DEMO)",headers:["Kode","Divisi","Temuan","Selisih","PIC","Tindakan","Status"],rows:[["DEMO-G01","Verpack–Gudang","Selisih sampel",20,"QC","Cocokkan bukti","OPEN RECON"],["DEMO-G02","Cukai","Selisih alokasi HJE",15,"Cukai","Periksa lot","WORKING"]]}
};
const $=id=>document.getElementById(id);const fmt=v=>typeof v==="number"?v.toLocaleString("id-ID"):String(v);
function rows(){const f=fixtures[$("report").value];return f.rows.filter(r=>(!$("sku").value||r[0].toLowerCase().includes($("sku").value.trim().toLowerCase()))&&(!$("status").value||r[r.length-1]===$("status").value))}
function render(){const f=fixtures[$("report").value];$("title").textContent=f.title;$("subtitle").textContent=f.subtitle;$("periodout").textContent=$("period").value||"Tidak dipilih";$("stampdate").textContent="Template cetak BAL";$("footerdate").textContent="Versi template: V04.";$("count").textContent=rows().length+" baris";$("thead").replaceChildren();const head=document.createElement("tr");for(const h of f.headers){const th=document.createElement("th");th.textContent=h;head.append(th)}$("thead").append(head);$("tbody").replaceChildren();for(const r of rows()){const tr=document.createElement("tr");for(const v of r){const td=document.createElement("td");td.textContent=fmt(v);if(typeof v==="number")td.className="num";tr.append(td)}$("tbody").append(tr)}}
function exportCSV(){const f=fixtures[$("report").value];const data=[f.headers,...rows()].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(",")).join("\r\n");const blob=new Blob(["\uFEFF"+data],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="BAL_DEMO_"+$("report").value+"_"+($("period").value||"periode")+".csv";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
for(const id of ["report","period","orientation","status"])$(id).addEventListener("change",render);$("sku").addEventListener("input",render);
$("print").addEventListener("click",()=>{let style=document.getElementById("print-orientation");if(!style){style=document.createElement("style");style.id="print-orientation";document.head.append(style)}style.textContent='@media print{@page{size:A4 '+$("orientation").value+';margin:13mm}}';window.print()});
$("csv").addEventListener("click",exportCSV);$("reset").addEventListener("click",()=>{$("report").value="stock";$("period").value="2026-11";$("orientation").value="portrait";$("sku").value="";$("status").value="";render()});render();